Write parametrized pytest tests for parse_date that accept several valid formats with descriptive ids, plus one invalid format case.

from datetime import datetime

def parse_date(text):
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%b %d %Y'):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    raise ValueError(text)

output:
import pytest
from dates import parse_date

@pytest.mark.parametrize('text, expected', [
    ('2024-03-15', '2024-03-15'),
    ('15/03/2024', '2024-03-15'),
    ('Mar 15 2024', '2024-03-15'),
], ids=['iso', 'european', 'abbrev-month'])
def test_parse_valid_dates(text, expected):
    assert parse_date(text).isoformat() == expected

def test_parse_invalid_date():
    with pytest.raises(ValueError):
        parse_date('not-a-date')

