Write parametrized pytest tests for roman_to_int with classic examples and boundary values.

def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, ch in enumerate(s):
        total += vals[ch]
        if i + 1 < len(s) and vals[ch] < vals[s[i + 1]]:
            total -= 2 * vals[ch]
    return total

output:
import pytest
from romans import roman_to_int

@pytest.mark.parametrize('roman, value', [
    ('I', 1), ('III', 3), ('IV', 4), ('IX', 9),
    ('LVIII', 58), ('MCMXCIV', 1994), ('MMMCMXCIX', 3999),
])
def test_roman_to_int(roman, value):
    assert roman_to_int(roman) == value

