Write a parametrized test for format_bytes covering 0 bytes, 1023, 1024 and multi-gigabyte values.

def format_bytes(n):
    units = ['B', 'KB', 'MB', 'GB']
    size = float(n)
    for unit in units:
        if size < 1024 or unit == units[-1]:
            return f'{size:.0f} {unit}' if unit == 'B' else f'{size:.1f} {unit}'
        size /= 1024

