Write parametrized tests for parse_kv pairs like 'k=v' with whitespace tolerance, covering malformed lines.

def parse_kv(text):
    if '=' not in text:
        raise ValueError(text)
    key, _, value = text.partition('=')
    return key.strip(), value.strip()

